  str_homeland_secret_msg_10103 = "ความสุภาพของเฟาสต์เป็นเพียงแค่หน้ากากเท่านั้น ถ้าเขาโมโหขึ้นมาล่ะก็...",
  str_homeland_secret_msg_10104 = "มีอากับบาบายาก้าเป็นพี่น้องฝาแฝด",
  str_homeland_secret_msg_10105 = "ที่จริงมีอาเป็นผีที่บาบายาก้าอัญเชิญมา!",
  str_homeland_secret_msg_10106 = "ที่จริงคุมะเป็นแค่หมีธรรมดานะ ไม่ใช่หมีขั้วโลก",
  str_homeland_secret_msg_10107 = "ดูเหมือนเพนจี้จะพูดได้เพราะออโรราในนอร์ธแลนด์",
  str_homeland_secret_msg_10108 = "เครื่องปรุงที่ไวซ์ใส่ลงในซุปครั้งที่แล้ว... เป็นผงปรุงรสที่ทำจากฟันของคอร์กอน...",
  str_homeland_secret_msg_10109 = "คอร์กอนพูดกับปลาได้ แต่จะพูดก็เฉพาะตอนที่เขาอยากกินพวกมันเท่านั้นแหละ",
  str_homeland_secret_msg_10110 = "เอโฮะทำงานหนักเพราะเธอมีครอบครัวใหญ่ที่ต้องดูแล",
  str_homeland_secret_msg_10111 = "อยู่ให้ห่างจากเอโฮะนะ เธอจะนำพาเคราะห์ร้ายมาให้!",
  str_homeland_secret_msg_10112 = "มีคนได้ยินบาร์ตันร้องไห้ในบ้านของเขา แล้วพูดว่า \"อยากมีสาวสักคนมาเล่นสงครามหมากรุกด้วยจังเล้ย\"",
  str_homeland_secret_msg_10113 = "แม้ว่าบาร์ตันจะเคยเป็นผู้บัญชาการกองทัพเรือ แต่เขาว่ายน้ำไม่เป็น",
  str_homeland_secret_msg_10114 = "บาร์ตันมีเพื่อนสนิทอยู่สอง... จะคนหรือตัวดีล่ะ เพราะเป็นสุนัขทั้งคู่เลย",
  str_homeland_secret_msg_10115 = "อย่าโกหกแชนดรานะ เธอมองปราดเดียวก็รู้แล้ว!",
  str_homeland_secret_msg_10116 = "แชนดราควบคุมจิตใจคุณได้! อย่ามองตาเธอเข้าล่ะ!",
  str_homeland_secret_msg_10117 = "เวลาแชนดราถอดแว่นออก เธอจะน่ากลัวสุด ๆ เลย!",
  str_homeland_secret_msg_10118 = "ก่อนที่จะเข้าร่วมอิลลูมินา ไวท์ดวาร์ฟเคยเป็นเจ้าชายที่ถูกเนรเทศ...",
  str_homeland_secret_msg_10119 = "ไวท์ดวาร์ฟสามารถทำลายได้ทั้งทวีปเลย... ถ้าเขาอยากจะทำ",
  str_homeland_secret_msg_10120 = "โคมไฟของนาดีนไม่เคยดับ... มันน่ารำคาญมากในตอนกลางคืน!",
  str_homeland_secret_msg_10121 = "นาดีนชอบกาแฟ มิน่าทำไมเธอถึงยังตื่นอยู่ทั้ง ๆ ที่ดึกขนาดนี้...",
  str_homeland_secret_msg_10122 = "ฉันได้ยินว่านาดีนละเมอ เธอออกเดินไปทั่วในตอนกลางคืน",
  str_homeland_secret_msg_10123 = "ได้ยินว่าเอมี่ไม่ผ่านการประเมินการต่อสู้อัศวิน เธอก็เลยฝึกฝนอย่างหนักไงล่ะ!",
  str_homeland_secret_msg_10124 = "เอมี่ชอบของหวาน เธอฝึกทุกวันเพื่อรักษาหุ่น",
  str_homeland_secret_msg_10125 = "เอมี่ใช้ธงเป็นผ้าปูนอนตอนที่เธอนอนนะ!",
  str_homeland_secret_msg_10126 = "เคลเคนคงตายแน่ถ้าเขาไปทะเลทราย...",
  str_homeland_secret_msg_10127 = "เคลเคนไม่เคยพูดความจริง",
  str_homeland_secret_msg_10128 = "มีคนบอกว่าในสมองของเคลเคน มีคราเคนตัวน้อยอยู่...",
  str_homeland_secret_msg_10129 = "มีแต่การดื่มถังน้ำขมและเค็มนั่นทุกวันเท่านั้นที่จะคลายความกระหายน้ำของเคลเคนได้",
  str_homeland_secret_msg_10130 = "โรบินสามารถเล่นดนตรีที่เหลือเชื่อได้โดยใช้แค่ท่อเท่านั้น",
  str_homeland_secret_msg_10131 = "ถ้าโรบินเสยผมปรกหน้าผากของเธอขึ้น... อัมบราตันทั้งเมืองคงยุ่งแน่",
  str_homeland_secret_msg_10132 = "ฉันได้ยินว่าเดย์นากับโรบินทะเลาะกันเมื่อคืนก่อนเพราะผู้ชายคนนึง",
  str_homeland_secret_msg_10133 = "แพตตี้กับแพตซี่ขึ้นไปร้องโหยหวนบนหลังคาทุกคืน",
  str_homeland_secret_msg_10134 = "แค่เอาคราดของแพตตี้กับแพตซี่ไปซะ พวกเธอก็จบเห่แล้ว",
  str_homeland_secret_msg_10135 = "หากคุณไปทำให้แพตตี้กับแพตซี่โมโหเข้า ก็แค่โยนกระดูกให้พวกเธอสักแท่งสิ",
  str_homeland_secret_msg_10136 = "มีคนบอกว่าได้ยินเสียงยิงปืนแปลก ๆ ตอนกลางคืน คาฟกาต้องกำลังฝึกซุ่มยิงใครอยู่แน่เลย",
  str_homeland_secret_msg_10137 = "อย่าได้ปลุกคาฟกาในตอนเช้าเด็ดขาด เธอได้ยิงคุณหัวหลุดแน่!",
  str_homeland_secret_msg_10138 = "ตอนที่ปืนไรเฟิลของคาฟกาพัง น้องหมาของเธอจะซ่อมให้",
  str_homeland_secret_msg_10139 = "ลือกันว่าองค์ราชินีมีพระชนมายุเป็นพันปีแล้ว",
  str_homeland_secret_msg_10140 = "เบธเลเฮมมีพี่สาวคนหนึ่ง... อยู่ที่ไหนสักแห่งในอิลลูมินา",
  str_homeland_secret_msg_10141 = "องค์ราชินีหยั่งรู้อนาคตได้! ถ้างั้น... ล็อตเตอรี่ของอัมบราตัน...",
  str_homeland_secret_msg_10142 = "เบธเลเฮมมีมังกรน้ำแข็งคอยรับใช้เธอ...",
  str_homeland_secret_msg_10143 = "วราธละเมอพูดว่าเธอชอบท่านจอมทัพ!",
  str_homeland_secret_msg_10144 = "วราธจะร้องไห้คิดถึงแม่ในเวลาที่เธอฝันร้าย",
  str_homeland_secret_msg_10145 = "วราธกับไรน์ฮาร์ตเป็นเพื่อนนักเรียนที่นั่งโต๊ะเดียวกัน! พวกเธอแลกสมุดบันทึกกันด้วยซ้ำ!",
  str_homeland_secret_msg_10146 = "อย่าปล่อยฟิลิชีให้อยู่กับชีสตามลำพัง",
  str_homeland_secret_msg_10147 = "มีข่าวลือว่าฟิลิชีเคยกินอิคลิพไซท์ นั่นเรื่องจริงเหรอ!?",
  str_homeland_secret_msg_10148 = "ฟิลิชีจะตายนะถ้าเธอกินชีสเข้าไป!",
  str_homeland_secret_msg_10149 = "ฟิลิชีค่อนข้างติดคน... ฉันได้ยินว่าเธออยู่ในห้องของผู้นำทางเมื่อไม่กี่วันที่แล้ว...",
  str_homeland_secret_msg_10150 = "ลิเลียมมีพี่น้องฝาแฝดอีก 7 คน และทุกคนอยู่ในอิลลูมินา!",
  str_homeland_secret_msg_10151 = "ลิเลียมนับได้ถึงแค่สาม เธอไม่สามารถเข้าใจอะไรได้มากไปกว่านั้น",
  str_homeland_secret_msg_10152 = "ที่จริงแล้วยูนิเมตซ่อมอะไรไม่เป็นเลย เป็นฝีมือของแขนจักรกลล้วน ๆ",
  str_homeland_secret_msg_10153 = "ยูนิเมตจะร่าเริงมากเมื่ออดนอนหลายวัน!",
  str_homeland_secret_msg_10154 = "ถ้าอิริดอนโกรธจัด จะมีสายฟ้าออกมาจากตาของเธอ!",
  str_homeland_secret_msg_10155 = "ฉันได้ยินว่าอิริดอนตัดสินประหารชีวิตผู้นำทางในตอนที่พวกเขาพบกันครั้งแรก!",
  str_homeland_secret_msg_10156 = "อิริดอนกลัวสายฟ้าสุด ๆ เธอจะหลบไปซ่อนที่ใต้เตียงทุกครั้งเลย",
  str_homeland_secret_msg_10157 = "มิคาเอลเล่าเรื่องตลกได้ขำกลิ้งสุด ๆ ปกติเธอจึงพยายามสงบนิ่งเข้าไว้",
  str_homeland_secret_msg_10158 = "ดูเหมือนว่ามิคาเอลจะชอบสะสมของตกแต่งทุกอย่าง",
  str_homeland_secret_msg_10159 = "บางคนว่ามิคาเอลความจำเสื่อมและจำอดีตของตัวเองไม่ได้เลย",
  str_homeland_secret_msg_10160 = "เมื่อไรที่ยูริอาห์หยุดยิ้ม เมื่อนั้นลูโมโพลิสถึงกาลอวสานแน่",
  str_homeland_secret_msg_10161 = "ยูริอาห์ร้องเพลงไม่เป็นหรอกนะ เธอแค่เนียนไปตามวงดนตรีเฉย ๆ",
  str_homeland_secret_msg_10162 = "อย่าได้หักหลังยูริอาห์เชียวนะ ไม่งั้นเธอหั่นคุณเป็นชิ้น ๆ แน่",
  str_homeland_secret_msg_10163 = "ฉันได้ยินว่ามิเชนนีแอบปรับหน่วยวัดบนตาชั่ง",
  str_homeland_secret_msg_10164 = "น้ำหนักของมิเชนนีหนักเท่า ๆ กับบ้านหลังนี้เลยนะ! เธอแข็งแกร่งสุด ๆ ไปเลย!",
  str_homeland_secret_msg_10165 = "มิเชนนีค่อนข้างขี้เหนียว เธอจะคำนวณอย่างละเอียดเวลาซื้อของ",
  str_homeland_secret_msg_10166 = "ฉันได้ยินว่าโคลอี้จะหยุดร้องไห้ถ้าเธอเห็นผู้นำทาง",
  str_homeland_secret_msg_10167 = "อย่าไปฟังเสียงดนตรีของโคลอี้นะ มันจะนำพาเคราะห์ร้ายมาให้",
  str_homeland_secret_msg_10168 = "โคลอี้เล่นพิณไม่เป็นเลย พิณนั่นเล่นเพลงเองต่างหาก...",
  str_homeland_secret_msg_10169 = "อีสต์วานควบคุมเงาของผู้คนได้ นั่นเป็นสาเหตุที่คนเรียกเขาว่าเจ้าแห่งเงา",
  str_homeland_secret_msg_10170 = "ว่ากันว่าอีสต์วานเป็นพี่น้องกับชวาตส์...",
  str_homeland_secret_msg_10171 = "เมื่อ 2-3 วันก่อน อีสต์วานเมาหนักและบอกว่าเขาจะขายอัมบราตันให้ผู้นำทาง",
  str_homeland_secret_msg_10172 = "ลีโอนาบอกว่าถ้าตามตัวน้องสาวเจอ เธอจะเกษียณและไปอยู่กับน้องสาว",
  str_homeland_secret_msg_10173 = "ฉันได้ยินว่าที่ลีโอนาโมโหมากก็เพราะผู้ชายคนหนึ่งทิ้งน้องสาวของเธอไป!",
  str_homeland_secret_msg_10174 = "ว่ากันว่าแซนเดอร์ออกมาจากไข่ที่ลีโอนาคายออกมา",
  str_homeland_secret_msg_10175 = "เจนเปิดกระเป๋าใบนั้นของเธอไม่ออก",
  str_homeland_secret_msg_10176 = "เจนชอบเอโฮะและโดฟ... หรือว่าเธอ...",
  str_homeland_secret_msg_10177 = "ภาพวาดบนกำแพงในส่วนที่อยู่อาศัยดูเหมือนจะเป็นฝีมือของเจน",
  str_homeland_secret_msg_10178 = "สองสามวันก่อนโจนาเล่นเป่ายิ้งฉุบกับแขนจักรกลของเธอ... แล้วก็แพ้...",
  str_homeland_secret_msg_10179 = "โจนามีมังกรสามหัวที่แม้แต่ซินซาก็ไม่กล้าแหยม",
  str_homeland_secret_msg_10180 = "ดูเหมือนโจนาจะมีความสุขที่ตัวเองถูกใส่กุญแจมือนะ...",
  str_homeland_secret_msg_10181 = "โจนากับซินซาเคยเป็นศัตรูคู่อาฆาตกัน!",
  str_homeland_secret_msg_10182 = "แม็กกี้เป็นมือระเบิดที่ยอดเยี่ยม! กระเป่าของเธอมีระเบิดเพียบเลยล่ะ!",
  str_homeland_secret_msg_10183 = "จุดอ่อนของแม็กกี้อยู่ที่หาง ถ้าคว้าปลายหางของเธอได้ เธอจะอ่อนเปลี้ยเพลียแรงเลยล่ะ",
  str_homeland_secret_msg_10184 = "ดูเหมือนแม็กกี้จะพูดกับกิ้งก่ายักษ์แห่งเรดีเซล เวรนช์นั่นได้นะ...",
  str_homeland_secret_msg_10185 = "แม้แต่โอดีที่ฝีปากจัดจ้าน ก็ยัง \"เถียง\" แพ้ผู้นำทางคราวที่แล้ว",
  str_homeland_secret_msg_10186 = "โอดีมีเพื่อนคนนึงชื่อโบรกรึไงเนี่ยแหละ เห็นเขาว่าเก่งมากถึงขนาดที่ลูโมโพลิสต้องการตัวเลยนะ!",
  str_homeland_secret_msg_10187 = "ว่ากันว่าโอดีออกจากการเรียนเพราะสอบไม่ติดโรงเรียนในอิลลูมินาที่เธออยากเข้า",
  str_homeland_secret_msg_10188 = "จริง ๆ แล้วบาร์บาร่าค่อนข้างเจ้าอารมณ์ คราวก่อนเธอถึงกับตีแฟนคลับคนนึงจนร้องไห้วิ่งหนีไปเลยนะ",
  str_homeland_secret_msg_10189 = "ดูเหมือนบาร์บาร่าจะไม่ชอบปลาซาชิมินะ เห็นทีไรเป็นต้องวิ่งหนีเลยล่ะ",
  str_homeland_secret_msg_10190 = "ลายเซ็นของบาร์บาร่าเป็นแบบพิมพ์ไว้ทั้งหมดเลย! ฉันเลิกรักเธอแล้วแหละ!",
  str_homeland_secret_msg_10191 = "ได้ยินว่าซินซาจะยกเรดีเซล เวรนช์ให้บร็อคดูแลต่อ",
  str_homeland_secret_msg_10192 = "บร็อคชอบทำความสะอาดและเก็บกวาดข้าวของ เขาเคยชนะที่หนึ่งในเรดีเซล เวรนช์เลยนะ",
  str_homeland_secret_msg_10193 = "บร็อคไม่เคยป่วยมาก่อนเลย คนโง่ก็ยังงี้แหละ...",
  str_homeland_secret_msg_10194 = "บร็อคเคยไปเดทที่ลูโมโพลิส กับใครคนหนึ่งในเรดีเซล เวรนช์",
  str_homeland_secret_msg_10195 = "โอฟินารวยนะ เธอเป็นเจ้าของเหมืองอัญมณีมีค่าแห่งหนึ่งในนอร์ธแลนด์",
  str_homeland_secret_msg_10196 = "โอฟินาอาจจะตัวเตี้ยแต่เธอตัวหนักมาก... หนักพอ ๆ กับบ้านหลังนี้เลยล่ะ",
  str_homeland_secret_msg_10197 = "อย่าได้ไปแตะเขาของโอฟินาเชียวล่ะ ไม่งั้นเธอจะเปลี่ยนเป็นคนละคนต่อหน้าต่อตาคุณเลย!",
  str_homeland_secret_msg_10198 = "ฉันเห็นแพกต์กำลังเล่นกับล้อของเธอบนหลังคา... ล้อนั่่นเหมือนมีชีวิตเลย...",
  str_homeland_secret_msg_10199 = "ดูเหมือนแพกต์จะตั้งใจขึ้นเป็นผู้นำ ทรู ออเดอร์ แทนที่วิกตอเรียนะ!",
  str_homeland_secret_msg_10200 = "ถ้าหิวขึ้นมาล่ะก็ แพกต์กินบ้านได้ทั้งหลังเลยล่ะ!",
  str_homeland_secret_msg_10201 = "เลือดของเนลส์เป็นสีขาว!",
  str_homeland_secret_msg_10202 = "เนลส์เป็นน้องชายที่หายสาปสูญไปนานของวิกตอเรีย เพราะงั้นเขาจึงเชื่อฟังวิกตอเรียเสมอ...",
  str_homeland_secret_msg_10203 = "ฉันได้ยินว่าเวนดี้สร้างจรวดมิสไซล์ในพายุเฮอร์ริเคนทะเลทรายได้!",
  str_homeland_secret_msg_10204 = "เวนดี้รอดชีวิตมาได้ด้วยการแกล้งตายหลายต่อหลายครั้ง!",
  str_homeland_secret_msg_10205 = "เวนดี้บินไม่ได้! เธอแค่พึ่งเจ็ตแพ็กของเธอถึงทำอย่างนั้นได้",
  str_homeland_secret_msg_10206 = "เปปีอยากเข้าร่วมทรู ออเดอร์จริง ๆ เธอยื่นใบสมัครตั้งหลายครั้งแล้ว",
  str_homeland_secret_msg_10207 = "\"ภูตวาจา\" ของเปปี ก็คือผ้าพันคอของเธอ",
  str_homeland_secret_msg_10208 = "วันก่อนฉันเห็นเปปีกับวิกตอเรียในส่วนที่อยู่อาศัยนะ พวกเธอดูจะสนิทกัน",
  str_homeland_secret_msg_10209 = "ซาริเอลซื้อถุงเท้าเหมือนกันมาหลายร้อยคู่เพื่อที่เธอจะเปลี่ยนได้ทันทีเวลาถุงเท้าขาด",
  str_homeland_secret_msg_10210 = "วันก่อนฉันเห็นซาริเอลใช้น้ำสีดำ ๆ ทำอาหารด้วยล่ะ...",
  str_homeland_secret_msg_10211 = "พ่อแม่ของซาริเอลเคยเป็นขุนนางของลูโมโพลิส!",
  str_homeland_secret_msg_10212 = "ตั้งแต่ที่เอซี่เข้าหอพักมา ก็มีเสียงร้องประหลาดให้ได้ยินในตอนกลางคืน...",
  str_homeland_secret_msg_10213 = "ดูเหมือนเอซี่จะเป็นลูกสาวของวิกตอเรียนะ เธอก็เลยเชื่อฟังวิกตอเรียมาก",
  str_homeland_secret_msg_10214 = "เอซี่จะทำให้ทุกคนทำตามคำสั่งของเธอได้ ถ้าเธอถอดผ้าปิดตาออก",
  str_homeland_secret_msg_10215 = "ผู้คนลือกันว่าเอซี่ย่องไปหาผู้นำทางกลางดึกอยู่บ่อย ๆ...",
  str_homeland_secret_msg_10216 = "ไม่กี่เดือนก่อนมิการ์ดไปอยู่กับผู้นำทางอยู่ช่วงหนึ่งเลยนะ เธอถึงได้รู้จักเคเลสไทต์ดีเหลือเกิน",
  str_homeland_secret_msg_10217 = "ได้ยินเสียงกรอบแกรบน่าขนลุกนั่นมั้ย? ดูเหมือนว่ามันจะมาจากสัตว์เลี้ยงของมิการ์ดนะ",
  str_homeland_secret_msg_10218 = "ครั้งหนึ่งมิการ์ดอยากลากโซรอซไปอิลลูมินาแล้วก็แยกส่วนมันซะ",
  str_homeland_secret_msg_10219 = "ดูท่าทางมิการ์ดอยากทำส่วนที่อยู่อาศัยให้เป็นห้องแล็บทดลองนะ... เหวออ...",
  str_homeland_secret_msg_10220 = "สองสามวันก่อนโคแร็กซ์ล้างมือของเขาทั้งคืนเลย เกิดอะไรขึ้น...?",
  str_homeland_secret_msg_10221 = "ที่จริงแล้วโคแร็กซ์เป็นช่างซ่อม เขาเป็นคนซ่อมโคลอสซัสครั้งก่อน",
  str_homeland_secret_msg_10222 = "มือของโคแร็กซ์เย็นเป็นน้ำแข็งเลย... ไม่เหมือนคนมีชีวิต",
  str_homeland_secret_msg_10223 = "เบนนี่สู้เก่งกว่าคุโระเยอะเลย",
  str_homeland_secret_msg_10224 = "คะแนนการยิงปืนของคุโระสูงกว่าเบนนี่มาก",
  str_homeland_secret_msg_10225 = "ทั้งเบนนี่กับคุโระต่างก็บอกรักผู้นำทางเมื่อ 2-3 วันก่อน พวกเธอบอกว่าผู้นำทางเป็น \"เป้าหมาย\" ที่ต้องการ...",
  str_homeland_secret_msg_10226 = "คุสคูตาไม่ชอบนอนบนเตียง เธอจึงนอนในป่าตลอดเลย",
  str_homeland_secret_msg_10227 = "แปลกจริงเชียว คนสวนที่เก่งอย่างคุสคูตาปลูกแต่ดอกกุหลาบสีดำ...",
  str_homeland_secret_msg_10228 = "ดูเหมือนคุสคูตาจะมีความรู้สึกพิเศษกับผู้นำทาง...",
  str_homeland_secret_msg_10229 = "ถ้าเด็ดหนามออกจากร่างของอาเรีย เธอจะล้มลง",
  str_homeland_secret_msg_10230 = "ดาบเวทมนตร์ของอาเรียพูดได้ มันบอกว่ามันเติบโตมากับอาเรีย",
  str_homeland_secret_msg_10231 = "ฉันเห็นผู้นำทางร้องไห้ใส่อาเรียไม่กี่วันก่อนนี่เอง...",
  str_homeland_secret_msg_10232 = "กล่องใบน้อยของซิคาเรมีเบาะแสที่พาไปยังสมบัติประจำตระกูลของเธอ...",
  str_homeland_secret_msg_10233 = "ฉันได้ยินมาว่าซิคาเรแต่งงานแล้วนะ! จริงหรือเปล่าเนี่ย!?",
  str_homeland_secret_msg_10234 = "ดูเหมือนว่า \"บอลหิมะ\" จะเป็นชื่อของสุนัขที่ซิคาเรเคยเลี้ยงไว้",
  str_homeland_secret_msg_10235 = "ฉันเห็นเบเวอร์ลีกับคารอนคุยกันเรื่องละครด้วยแหละ!",
  str_homeland_secret_msg_10236 = "ไม่กี่วันก่อนฉันเห็นผู้นำทางขี่หอกสายฟ้าที่เบเวอร์ลีเสกขึ้นมา บินไปรอบ ๆ เลย!",
  str_homeland_secret_msg_10237 = "หอกด้ามนั้นของคาร์ลีน ดูเหมือนเบเวอร์ลีจะเป็นคนทำขึ้นมานะ",
  str_homeland_secret_msg_10238 = "คอนสแตนตินน่าจะเคยไปนอร์ธแลนด์มาก่อน และเคยเป็นองครักษ์รับใช้ราชินีเบธเลเฮมด้วยนะ",
  str_homeland_secret_msg_10239 = "จริง ๆ แล้วคอนสแตนตินใช้ปืนไม่เป็นหรอก ปกติเขาก็แค่ใช้พานท้ายปืนตีศัตรูเท่านั้นเอง",
  str_homeland_secret_msg_10240 = "เลสเตอร์ไปเที่ยวมาหลายที่แล้ว แม้แต่ตะวันออกไกล!",
  str_homeland_secret_msg_10241 = "เลสเตอร์เรียกทุกคนว่า \"ท่าน\" ไม่ว่าจะเพศอะไรหรืออายุเท่าไร...",
  str_homeland_secret_msg_10242 = "ฉันได้ยินว่าเลสเตอร์วางแผนที่จะเกษียณจากงานปัจจุบันและทำงานเป็นผู้จัดการหอพัก",
  str_homeland_secret_msg_10243 = "มือของซิลวาเปลี่ยนเป็นดาบยาวได้ด้วยนะ!",
  str_homeland_secret_msg_10244 = "ซิลวาสามารถเปลี่ยนไม้ให้เป็นเหล็กได้",
  str_homeland_secret_msg_10245 = "แอนเซียเป็นคนเสียงเบาสุด ๆ นั่นเป็นสาเหตุที่เธอใช้ลำโพง",
  str_homeland_secret_msg_10246 = "แอนเซียอาจจะอยากเข้าร่วมกับเรดีเซล เวรนช์ เพราะอยากฟังดนตรีอะไรแบบนั้นของพวกเขา",
  str_homeland_secret_msg_10247 = "จริง ๆ แล้วแอนเซียมีสายตาที่ดีมาก เธอมองเห็นแม้แต่สีตาของนกจากระยะไกล",
  str_homeland_secret_msg_10248 = "เทสซาชกมวยเก่ง เธอเป็นแชมป์ตลอดฤดูกาลในอัมบราตันเลยนะ!",
  str_homeland_secret_msg_10249 = "ฟันของเทสซาเป็นฟันปลอมทั้งปาก เธอก็เลยกินของหวานได้โดยไม่ต้องกลัวฟันหลอ!",
  str_homeland_secret_msg_10250 = "ฉันเห็นเทสซากับสโมกกี้เดินช้อปปิ้งไปตามถนนที่อัมบราตัน แถมยังดริ๊งกันคนละแก้วด้วยนาา... ฮืมมม...",
  str_homeland_secret_msg_10251 = "ฉันได้ยินว่าตราบใดที่ลีอาห์ยังอยู่ จะไม่มีทางขาดน้ำเปล่าในหอพัก",
  str_homeland_secret_msg_10252 = "ไม่กี่วันก่อนฉันเห็นผู้นำทางลอยขึ้นไปบนยอดเขาใกล้ ๆ ในฟองสบู่ของลีอาห์แน่ะ!",
  str_homeland_secret_msg_10253 = "ดอกไม้ใดก็ตามที่ลีอาห์แตะต้องจะบานโดยทันทีเลยล่ะ!",
  str_homeland_secret_msg_10254 = "ครั้งก่อนโนวิโอคิดว่าอลิซเป็นกระต่ายและพาเธอไปที่พระราชวังเหมันต์",
  str_homeland_secret_msg_10255 = "ว่ากันว่าอลิซเก็บตุ๊กตา 2 ตัวนั้นมาจากในป่าเมื่อครั้งที่เธอนอนละเมอ",
  str_homeland_secret_msg_10256 = "อลิซชอบอาหารเผ็ด พอกินแล้วเธอจะพ่นไฟออกมาได้ด้วยนะ!",
  str_homeland_secret_msg_10257 = "ขวดน้ำที่เข็มขัดของซินซามีทั้งน้ำร้อนและน้ำเย็นไว้ให้อีฟดื่ม",
  str_homeland_secret_msg_10258 = "ซินซาทำคิลเลอร์ชิชเคบับอร่อยมาก ครั้งก่อนเขาถึงกับพูดว่าอยากไปเป็นคนขายชิชเคบับมากกว่าเป็นลูกพี่",
  str_homeland_secret_msg_10259 = "ครั้งก่อนฉันเห็นซินซากดตัวผู้นำทางไว้แล้วพูดประมาณว่า \"อย่ามาทำตัวแบบนี้นะ\"",
  str_homeland_secret_msg_10260 = "ได้ยินว่าอีฟเคยสวมชุดที่พิเศษมาก ๆ ให้ผู้นำทางดูโดยเฉพาะ!",
  str_homeland_secret_msg_10261 = "หมู่นี้อีฟไปเยี่ยมเซลูซิดบ่อย ทำยังกับว่าเขาเป็นแมวตัวใหญ่งั้นแหละ",
  str_homeland_secret_msg_10262 = "ดูเหมือนว่าอีฟจะยกโซรอซได้ด้วยมือข้างเดียวนะ",
  str_homeland_secret_msg_10263 = "ครั้งก่อนฉันเห็นอีฟ ซินซา และผู้นำทางไปปิกนิกด้วยกัน อีฟยังพูดประมาณว่าพวกเขาเป็น \"ครอบครัว\" อะไรทำนองนั้นด้วยนะ...",
  str_homeland_secret_msg_10264 = "วันก่อนฉันเห็นดอว์นให้ดอกไม้กับอีฟ หรือว่าพวกเธอจะเป็น...",
  str_homeland_secret_msg_10265 = "ฉันได้ยินว่าหุบเขาตาแดงเป็นของดอว์นแต่ยกให้ผู้นำทางไปแล้ว",
  str_homeland_secret_msg_10266 = "ดอว์นเคยเลี้ยงอิคลิพไซท์ด้วยนะเธอ!",
  str_homeland_secret_msg_10267 = "ทาคิดื่มไวน์ได้แค่แก้วเดียวก็ไม่ไหวแล้ว",
  str_homeland_secret_msg_10268 = "ทาคิมาที่อัมบราตันเพราะเขาเล่นพนันจนหมดตัวที่ตะวันออกไกล",
  str_homeland_secret_msg_10269 = "หมู่นี้ร้านรับงานจิปาถะของทาคิไม่ค่อยได้งานเลย คงจะต้องเลิกกิจการในเร็ว ๆ นี้แหละ!",
  str_homeland_secret_msg_10270 = "ช่วงนี้มีคริสตัลสีแดงในหอพักเยอะขึ้นมากเลย มีใครถูกล็อตเตอรี่เลยทิ้งเพชรพลอยไปทั่วรึไงกัน?",
  str_homeland_secret_msg_10271 = "ไม่กี่วันก่อนเบริลไปหาเฟาสต์ แล้วก็มีเสียงแปลก ๆ ออกมาจากห้องของเฟาสต์...",
  str_homeland_secret_msg_10272 = "ลือกันว่าเบริลเคยเป็นขุนนางของลูโมโพลิสด้วย เธอหนีออกมาเมื่อครอบครัวเธอมีปัญหาอะไรบางอย่าง",
  str_homeland_secret_msg_10273 = "น้ำตาของเบริลจะกลายเป็นทับทิม!",
  str_homeland_secret_msg_10274 = "ดูเหมือนว่าในอดีตสโมกกี้จะเคยปราบมันติคอร์ด้วย! มันเป็นสิ่งมีชีวิตในตำนานเลยนะ!",
  str_homeland_secret_msg_10275 = "สโมกกี้ดูจะไม่รู้สึกเจ็บปวดอะไรเลย",
  str_homeland_secret_msg_10276 = "ตอนที่สโมกกี้มาถึงอัมบราตันครั้งแรก เธอเผาถนนทั้งเส้นเสียวอดวายเลยล่ะ...",
  str_homeland_secret_msg_10277 = "สโมกกี้มีแว่นกันแดดหลายร้อยอันและเธอสวมไม่ซ้ำกันในแต่ละวันเลยล่ะ",
  str_homeland_secret_msg_10278 = "คุณรู้อะไรเกี่ยวกับกิ้งก่ายักษ์ในเรดีเซล เวรนช์นั่นมั้ย? เฟลอร์เป็นคนสร้างมันขึ้นมานะ!",
  str_homeland_secret_msg_10279 = "ดูเหมือนเฟลอร์จะถูกผู้หญิงคนนึงลักพาตัวไปโดยใช้ปืนลูกโม่แล้วก็ส่งตัวให้กับเรดีเซล เวรนช์",
  str_homeland_secret_msg_10280 = "ฉันได้ยินว่าเฟลอร์หนีออกมาเพราะเขาถูกผู้บังคับบัญชาในอิลลูมินารังควาญ",
  str_homeland_secret_msg_10281 = "ว่ากันว่าบ้านของโบนาชีพังเพราะเธอทำลายเอง",
  str_homeland_secret_msg_10282 = "ครั้งก่อนที่โบนาชีแสดงคอนเสิร์ตแม้แต่โซรอซก็เต้นเพลงของเธอล่ะ",
  str_homeland_secret_msg_10283 = "ถึงโบนาชีจะรักในเสียงดนตรีขนาดไหน แต่เธอก็แต่งเพลงไม่เป็นเลย เธอแค่ทำท่าเหมือนคอนดักเตอร์ไปอย่างนั้นเอง",
  str_homeland_secret_msg_10284 = "เจเนวีฟกับสโมกกี้ต้องเป็นคู่กันแน่เลย เห็นพวกเธออยู่ด้วยกันตลอด",
  str_homeland_secret_msg_10285 = "ครั้งก่อนที่เจเนวีฟเมา ฉันได้ยินว่าเธอ \"ทำอะไร\" ผู้นำทางก็ไม่รู้ ในหอพัก...",
  str_homeland_secret_msg_10286 = "ฉันได้ยินว่าเจเนวีฟเสกหญิงรับใช้ของเธอให้กลายเป็นม้า ม้านั่นถึงได้ชื่อว่า \"แอนนา\" ไง...",
  str_homeland_secret_msg_10287 = "พาโซโล่ลายมือสวยมาก เธอฝึกเขียนทุกวันในหอพัก เธอถึงได้พกกระดาษติดตัวเยอะเลยไงล่ะ",
  str_homeland_secret_msg_10288 = "ไม่กี่วันก่อนผู้นำทางเล่านิทานให้พาโซโล่ฟัง จนเธอร้องไห้เลย...",
  str_homeland_secret_msg_10289 = "ตั้งแต่พาโซโล่มาอยู่ที่หอพัก พื้นก็ไม่เคยสะอาดอีกเลย เพราะจะมีเศษกระดาษหล่นกระจายไปทั่วพื้นอยู่ตลอด!",
  str_homeland_secret_msg_10290 = "ลุงแกรมน่ะ แค่ดื่มโซดาก็เมาได้",
  str_homeland_secret_msg_10291 = "ดูเหมือนแกรมจะเป็นคนทำอาหารทั้งหมดที่เสิร์ฟที่หอพักนะ",
  str_homeland_secret_msg_10292 = "เมื่อคืนฉันได้ยินเสียงเครื่องยนต์รถดังกระหึ่ม แกรมต้องขับรถออกไปซิ่งแน่ ๆ!",
  str_homeland_secret_msg_10293 = "ฉันว่าเรวี่กินอะไรเผ็ด ๆ ไม่ได้หรอก ครั้งหนึ่งฉันเคยเห็นเธอน้ำตาไหลไปทั้งวันหลังจากที่กินเค้กรสเผ็ดน่ะ",
  str_homeland_secret_msg_10294 = "ครั้งก่อนเรวี่เรียกผู้นำทางว่า \"คนดี\" แหละ หรือจะหมายความว่า...",
  str_homeland_secret_msg_10295 = "ดาบของเรวี่ต้องทำจากไม้แน่ ไม่อย่างนั้นเธอจะยกมันขึ้นได้ยังไงกัน?",
  str_homeland_secret_msg_10296 = "ฉันได้ยินว่าผู้นำทางกับอัลลัวราเปิดร้านขายของเก่าด้วยกันในอัมบราตัน ขายของเคเลสไทต์ในราคาถูกล่ะ!",
  str_homeland_secret_msg_10297 = "ดูเหมือนอัลลัวราจะลงทุนในสหภาพผู้ส่งสารนะ!",
  str_homeland_secret_msg_10298 = "ฉันได้ยินว่าอัลลัวราย้ายเข้ามาในหอพักก็เพื่อดูว่าเธอจะซื้อหอพักดีไหม",
  str_homeland_secret_msg_10299 = "พาโลม่าเคยทำงานที่โบสถ์ลูโมโพลิส เธอถูกไล่ออกมาเพราะทำรูปปั้นหรืออะไรแตกนี่แหละ",
  str_homeland_secret_msg_10300 = "แพกต์กับพาโลม่าเป็นพี่น้องที่พลัดพรากจากกันไปนาน!",
  str_homeland_secret_msg_10301 = "พาโลม่ากับพิตต์แมนเป็นเพื่อนร่วมชั้นเรียน ที่จริงพวกเขารู้จักกันมาก่อนนะ!",
  str_homeland_secret_msg_10302 = "ไม่กี่วันก่อนฉันเห็นผู้นำทางขี่ลาของนาโรเซลไปรอบสวน ทำให้เธอโมโหน่าดูเลยล่ะ...",
  str_homeland_secret_msg_10303 = "ดูท่านาโรเซลจะสื่อสารกับต้นไม้ได้นะ พวกมันเป็นหูเป็นตาให้เธอ",
  str_homeland_secret_msg_10304 = "นาโรเซลกลัวความหนาวสุด ๆ ดังนั้นเธอจะไม่เข้าใกล้นอร์ธแลนด์อย่างเด็ดขาด",
  str_homeland_secret_msg_10305 = "ทวีตตี้เป็นผู้เชี่ยวชาญในการเล่นปาหิมะ! ไม่มีใครในหอพักเอาชนะเธอได้เลย!",
  str_homeland_secret_msg_10306 = "ทวีตตี้เป็นเจ้าของโรงแรมในตะวันออกไกลเชียวนะ! ที่จริงเธอเป็นเศรษฐีนีนะจะบอกให้!",
  str_homeland_secret_msg_10307 = "ฉันได้ยินว่าทวีตตี้เคยคิดจะใช้หิมะมาสร้างเป็นหอพักให้ทุกคน... ดีที่ไม่เกิดขึ้นจริง",
  str_homeland_secret_msg_10308 = "ดูเหมือนสัตว์เลี้ยงของเบเธลจะกินอาหารในหอพักจนเกลี้ยงแล้ว",
  str_homeland_secret_msg_10309 = "จริง ๆ แล้วเบเธลเป็นนักเขียนชื่อดังในอัมบราตันล่ะ!",
  str_homeland_secret_msg_10310 = "ฉันได้ยินว่าเบเธลเป็นลูกสาวของอีสต์วานนะ!",
  str_homeland_secret_msg_10311 = "ฉันเห็นลุคสเก็ตช์ภาพผู้นำทางวันก่อน เขาตั้งใจเต็มที่เลย",
  str_homeland_secret_msg_10312 = "ทันทีที่ลุคสวมเสื้อแจ็กเก็ตของเขาตัวนั้น เขาก็จะกลายเป็นผีเสื้อบินไปเลย",
  str_homeland_secret_msg_10313 = "อย่าได้จับผีเสื้อเลยเชียว ลุคจะส่งทหารรับจ้างมาจัดการคุณ",
  str_homeland_secret_msg_10314 = "พิตต์แมนเคยจับคู่กับเทสซาประลองในอารีน่าใต้ดินที่อัมบราตัน แถมยังเคยเป็นแชมป์ด้วยนะ",
  str_homeland_secret_msg_10315 = "พิตต์แมนเสียแขนของเขาเพราะอิคลิพไซท์ในอัมบราตัน",
  str_homeland_secret_msg_10316 = "พิตต์แมนเป็นนักอ่านเร็ว เขาอ่านไฟล์ต่าง ๆ เป็นกองในแต่ละวัน",
  str_homeland_secret_msg_10317 = "ฉันได้ยินว่าในลูโมโพลิส อาหารของเฮดี้แต่ละมื้อมีราคาเป็นล้านไนท์เทียม!",
  str_homeland_secret_msg_10318 = "วันก่อนผู้นำทางเผลอจับมือเฮดี้โดยไม่ได้ตั้งใจ... เขาถูกปอมเปย์ลงโทษอย่างหนักเลย",
  str_homeland_secret_msg_10319 = "เฮดี้ดูไม่ค่อยพอใจหอพักเท่าไร เธออยากสร้างหอพักใหม่",
  str_homeland_secret_msg_10320 = "ฉันเห็นคอร์ดี้ร้องไห้กับผู้นำทางเมื่อวันก่อน แล้วก็เอาแต่พูดว่า \"ขอโทษ\"...",
  str_homeland_secret_msg_10321 = "แม้ว่าคอร์ดี้จะอายุน้อย แต่เธอก็เป็นผู้พิทักษ์กฎระดับสูงในอิลลูมินานะ!",
  str_homeland_secret_msg_10322 = "ไม่กี่วันก่อนมีคนเห็นคอร์ดี้ทานอาหารมื้อดึกตั้ง 3 จานแน่ะ",
  str_homeland_secret_msg_10323 = "ฉันได้ยินว่าฮาชิกับกินวางแผนที่จะซื้อโซรอซ พวกเขาก็เลยมาที่นี่ไงล่ะ!",
  str_homeland_secret_msg_10324 = "อย่าได้แตะต้องคางของฮาชิเข้าล่ะ เขาจะตื่นกลัว",
  str_homeland_secret_msg_10325 = "ดูเหมือนว่าเจ้ากิน คู่หูฮาชิ จะไม่มีหางนะ...",
  str_homeland_secret_msg_10326 = "บ้านเกิดของโนวิโอเป็นชนเผ่าป่าเถื่อนอยู่ลึกเข้าไปในภูเขาแห่งนอร์ธแลนด์",
  str_homeland_secret_msg_10327 = "ท่าทางคทาของโนวิโอจะพูดได้นะ!",
  str_homeland_secret_msg_10328 = "ดูเหมือนโนวิโอจะเป็นคนสร้างพระราชวังเหมันต์ของราชินีเบธเลเฮม",
  str_homeland_secret_msg_10329 = "แท้ที่จริงแล้วโลล่าเป็นกระต่ายนอร์ธแลนด์ที่กลายเป็นออโรเรียน!",
  str_homeland_secret_msg_10330 = "อย่าไปแตะต้องรอยบนคอของโลล่าล่ะ ไม่งั้นเธอจะตามล่าคุณแน่!",
  str_homeland_secret_msg_10331 = "เมื่อคืนก่อนฉันผ่านห้องครัวและเห็นโลล่ากำลังละเมอกินอาหาร...",
  str_homeland_secret_msg_10332 = "ตั้งแต่เชอวานเข้ามาในหอพักนี้ ก็เจอตาข่ายประหลาดบนหลังคา...",
  str_homeland_secret_msg_10333 = "จริง ๆ แล้วเชอวานเองเป็นคนโบราณ นั่นคือสาเหตุที่เธอสนใจในซากปรักหักพังโบราณมาก",
  str_homeland_secret_msg_10334 = "อย่าให้เชอวานอยู่กับกรอนรู 2 คนนะ พวกเธอจะทำอะไรไม่ถูกเลยถ้าเป็นอย่างนั้น",
  str_homeland_secret_msg_10335 = "เอริก้าดูยังกับมาจากต่างโลกแน่ะ ไม่อย่างนั้นเธอจะพูดจาพิลึก ๆ แบบนั้นได้ยังไงกัน?",
  str_homeland_secret_msg_10336 = "ที่จริงแล้วเอริก้าเป็นนักพยากรณ์นะ สิ่งที่เธอทำนายกลายเป็นจริงหลายอย่างเลย!",
  str_homeland_secret_msg_10337 = "เมื่อไม่กี่วันก่อนเอริก้าทำนายให้ผู้นำทาง บอกว่าผู้นำทางกับไวซ์จะ...",
  str_homeland_secret_msg_10338 = "เสื้อผ้าประหลาดที่ฟลอรีนสวมใส่ดูเหมือนจะซื้อมาจากอิลลูมินา",
  str_homeland_secret_msg_10339 = "ดาบของฟลอรีนจริง ๆ แล้วเป็นไม้เท้ารักษา!",
  str_homeland_secret_msg_10340 = "งูของฟลอรีนวิ่งเข้าไปในหอพักแล้วก็หายไปเลย...",
  str_homeland_secret_msg_10341 = "รูบี้ต่อยกำแพงในหอพักเป็นรูตอนที่เล่นบาสเก็ตบอล... เธอเกือบจะพังหอพักทั้งหลังอยู่แล้ว!",
  str_homeland_secret_msg_10342 = "รูบี้อาจจะเป็นนักสำรวจที่กระตือรือร้น แต่เรื่องทิศทางนี่ อย่าไปถามเธอเลยนะ",
  str_homeland_secret_msg_10343 = "รูบี้บอกว่าวันหนึ่งแฮมสเตอร์ของเธอจะกอบกู้โลก...",
  str_homeland_secret_msg_10344 = "ฉันได้ยินว่าแฮมสเตอร์ของรูบี้จริง ๆ แล้วเป็นอาหารฉุกเฉินของเธอในยามจำเป็น",
  str_homeland_secret_msg_10345 = "ที่จริงรูจเป็นวีแกนนะ เธอแค่ชอบกลิ่นเนื้อเท่านั้นเอง",
  str_homeland_secret_msg_10346 = "จริง ๆ แล้วรูจไม่กลัวผีเลย เธอแค่แกล้งทำเป็นกลัวเพื่อรูบี้เท่านั้น",
  str_homeland_secret_msg_10347 = "รูจต้องการการนอนแค่วันละ 1 ชั่วโมงเท่านั้น ดังนั้นเวลาส่วนใหญ่เธอแค่แกล้งหลับ",
  str_homeland_secret_msg_10348 = "ในหอพักมีผี! รินเนะพบว่านี่เป็นเรื่องจริงทันทีที่เธอมาถึงที่นี่!",
  str_homeland_secret_msg_10349 = "ดูเหมือนว่ารินเนะจะทำนายความรักได้นะ ครั้งก่อนเธอบอกว่าเหยากับอาเมะโมริจะ...",
  str_homeland_secret_msg_10350 = "ถ้ากระดิ่งรำบวงสรวงของรินเนะดังขึ้นเองล่ะก็ แปลว่าเรื่องร้ายกำลังจะเกิดขึ้น",
  str_homeland_secret_msg_10351 = "ดูเหมือนว่ารินเนะจะเคยบำเพ็ญเพียรในสถานที่อันไกลโพ้นมาก่อน",
  str_homeland_secret_msg_10352 = "ฉันได้ยินว่าคายาโนะย้ายเข้าหอพักแล้ว มีใครเห็นเธอบ้างมั้ย?",
  str_homeland_secret_msg_10353 = "คายาโนะไม่ใช่ออโรเรียนเหรอ? ไม่อย่างนั้นทำไมเธอต้องกลัวคนอื่น ๆ ขนาดนั้นล่ะ?",
  str_homeland_secret_msg_10354 = "คายาโนะไม่ได้เดินนะ เธอลอยต่างหากล่ะ",
  str_homeland_secret_msg_10355 = "อาเมะโมริต้องการการนอนวันละ 16 ชั่วโมงขึ้นไป แต่เธอก็ตื่นตัวแม้ในขณะที่นอนหลับ",
  str_homeland_secret_msg_10356 = "อาเมะโมริเกลียดกระเทียม!",
  str_homeland_secret_msg_10357 = "อาเมะโมริล่องหนได้ ทุกคน อยู่ในหอพักต้องระวังตัวกันด้วยนะ!",
  str_homeland_secret_msg_10358 = "ไม่กี่วันก่อนเหยาเกือบกินหมอนของเธอตอนที่นอนอยู่ จริง ๆ นะ ฉันเห็นกับตาเลย!",
  str_homeland_secret_msg_10359 = "เหยาว่ายน้ำไม่เป็น แต่เธอลอยตัวบนผิวน้ำได้เก่งมาก",
  str_homeland_secret_msg_10360 = "แม้แต่ตอนที่เหยายังเด็ก เธอก็ชนะพวกโจรสลัดมานับพัน ๆ คน!",
  str_homeland_secret_msg_10361 = "ฉันเห็นเหยาแบ่ง \"เต้าหู้ไม่เผ็ด\" ให้ไวซ์ด้วย แล้วจากนั้น...",
  str_homeland_secret_msg_10362 = "ตอนที่โมโมะทำบัญชี เธอจะแอบเพิ่มยอดค่าใช้จ่ายของสินค้าที่ซื้อไป!",
  str_homeland_secret_msg_10363 = "อันสึจะใช้นิ้วของเธอชิมซุปที่เธอทำเสมอเลย!",
  str_homeland_secret_msg_10364 = "ร้านราเม็งของโมโมะและอันสึกำลังจะเปิดสาขาที่นี่!",
  str_homeland_secret_msg_10365 = "เกมของทัวร์ด็อกทำเงินได้มหาศาลเลยเชียวล่ะ!",
  str_homeland_secret_msg_10366 = "เมื่อเข้าโหมดทำงาน ทัวร์ด็อกสามารถทำงานได้วันละ 25 ชั่วโมงเลยนะ!",
  str_homeland_secret_msg_10367 = "ดูเหมือนจะมีขุนนางบางคนในลูโมโพลิสลงทุนให้ทัวร์ด็อกนะ...",
  str_homeland_secret_msg_10368 = "ฉันได้ยินมาว่าแอเชอร์จะแช่แข็งคนที่เธอชอบ!",
  str_homeland_secret_msg_10369 = "ยิ่งแอเชอร์เมา เธอก็ยิ่งขับรถได้ดีขึ้น!",
  str_homeland_secret_msg_10370 = "แอเชอร์มักจะพาผู้นำทางไปซิ่งรถอยู่บ่อย ๆ เธอคงอยากจะรับเขาเป็นลูกศิษย์สินะ",
  str_homeland_secret_msg_10371 = "ดูเหมือนแอเชอร์จะตั้งชื่อเล่นใหม่ให้รถของเธอว่า \"เคเลสไทต์สุดหล่อ\"",
  str_homeland_secret_msg_10372 = "รอยไม่ได้เรียกผึ้งหุ่นยนต์ของเขาว่า \"สวีทตี้\" เท่านั้น ยังเรียกว่า \"เคลี่\" และ \"แอเชอร์รี่\" ด้วย...",
  str_homeland_secret_msg_10373 = "ครั้งก่อนที่หิ่งห้อยระบบล่ม รอยแค่เตะมันก็หายเลย...",
  str_homeland_secret_msg_10374 = "ฉันเคยเห็นรอยสอนผู้นำทางเย็บผ้าด้วยล่ะ ไม่คิดเลยว่าเขาจะมีฝีมือในเรื่องพวกนี้...",
  str_homeland_secret_msg_10375 = "กระเป๋าแมวขาวตัวน้อยของเมย์เดิมทีมีสองตา แต่อยู่ ๆ ก็งอกมาอีกคู่...",
  str_homeland_secret_msg_10376 = "ถ้าแมวขาวของเมย์พูดกับใคร คนนั้นจะโชคดี!",
  str_homeland_secret_msg_10377 = "ครั้งก่อนเมย์ทำผมทรงทวินเทลให้ผู้นำทางด้วย น่ารักมากเลยล่ะ!",
  str_homeland_secret_msg_10378 = "เลนอร์จะขยับไม่ได้เลยถ้าเธอไม่ได้แตะหู เธอบอกว่ามันเป็น \"สปริงดึง\" ของเธอ",
  str_homeland_secret_msg_10379 = "วันก่อนฉันเห็นเลนอร์ยิ้มให้ผู้นำทางแล้วก็ชวนผู้นำทางเข้าห้องเธอด้วยล่ะ!",
  str_homeland_secret_msg_10380 = "ถ้าสังเกตดูใกล้ ๆ จะเห็นว่าเลนอร์ไม่มีม่านตานะ",
  str_homeland_secret_msg_10381 = "เขาบนหัวของไจลส์จะสูงขึ้นเรื่อย ๆ มันจะสูงขึ้นไปจนเท่าตึก 2 ชั้นเลยนะ!",
  str_homeland_secret_msg_10382 = "วันก่อนฉันเห็นไจลส์เลี้ยงอีกาในหอพักด้วยล่ะ!",
  str_homeland_secret_msg_10383 = "ทันทีที่ไจลส์ย้ายเข้ามา เราก็ได้ยินเสียงอ่านเพลงกล่อมเด็กอันน่าขนลุกยามค่ำคืนในหอพักนี้...",
  str_homeland_secret_msg_10384 = "ไม่กี่วันก่อนไรน์ฮาร์ตเปิดขวดน้ำเองไม่ออก ต้องให้ผู้นำทางช่วยเปิดให้",
  str_homeland_secret_msg_10385 = "ฉันเห็นไรน์ฮาร์ตแอบอ่านนิยายรักด้วย!",
  str_homeland_secret_msg_10386 = "มีใครเคยเห็นรูปไรน์ฮาร์ตสมัยที่เธอผมสั้นมั้ย? น่ารักมาก ๆ เลยนะ!",
  str_homeland_secret_msg_10387 = "ลือกันว่าจริง ๆ แล้วไรน์ฮาร์ตเป็นผู้ชาย!",
  str_homeland_secret_msg_10388 = "มีรังสีพิฆาตออกมาจากดวงตาของไวซ์!",
  str_homeland_secret_msg_10389 = "ฉันได้ยินมาว่าจริง ๆ แล้วไวซ์มีแฝดที่หน้าตาเหมือนเธอเป๊ะเลย!",
  str_homeland_secret_msg_10390 = "ตอนนี้ที่ไวซ์ได้เลื่อนขั้นแล้ว เธอถึงกับเปลี่ยนเสื้อผ้าใหม่หมดทั้งตู้เลยล่ะ!",
  str_homeland_secret_msg_10391 = "ฉันได้ยินว่าช่วงนี้ {1} ไม่สบาย แม้แต่แขนยังแปลกประหลาดไปเลย...",
  str_homeland_secret_msg_10392 = "{1} หัวเราะอย่างบ้าคลั่งในหอพักเมื่อวันก่อน บอกว่าวันที่จะกลายเป็น \"นายพลที่แท้จริงแห่งอิลลูมินา\" อยู่แค่เอื้อมแล้ว... แล้วตอนนี้ใครเป็นนายพลแห่งอิลลูมินาอยู่ล่ะ?",
  str_homeland_secret_msg_10393 = "ฉันเห็น {1} ใช้ดาบสองปลายจับปลา เขาใช้ดาบนั่นย่างปลาด้วยซ้ำ!",
  str_homeland_secret_msg_10394 = "มีคนบอกว่าไวซ์เคยทำกิ๊บหาย แต่สุดท้ายก็หาเจอ... เธอติดมันไว้ที่ด้านหลังศีรษะ",
  str_homeland_secret_msg_10395 = "ว่ากันว่ามิสบลังค์ไปเที่ยวที่ต่าง ๆ โดยพกชุดชงชาครบเซ็ต!",
  str_homeland_secret_msg_10396 = "ว่ากันว่าโดฟมีพัสดุกองอยู่ล้นคลัง รอให้เธอนำไปส่ง!",
  str_homeland_secret_msg_10397 = "ได้ยินว่าอาวุธของราฟาเอลหนักเท่าบ้านหลังนึงเลยนะ!",
  str_homeland_secret_msg_10398 = "นิคินิสจะส่องกระจกและจัดดอกไม้ที่ประดับบนศีรษะของเธอเมื่อไม่มีใครจ้องมอง",
  str_homeland_secret_msg_10399 = "เขาลือกันว่านีน่าเป็นดีลเลอร์ค้าอาวุธ!",
  str_homeland_secret_msg_10400 = "ตั้งแต่นีน่าย้ายเข้ามา ผ้าม่านทุกผืนก็กลายเป็นสีดำ!",
  str_homeland_secret_msg_10401 = "มีคนบอกว่านีน่าไม่กลัวผีแม้แต่น้อย แถมยังชอบคุยกับผีอีกต่างหาก!",
  str_homeland_secret_msg_10402 = "นีน่ามักจะกางร่มไว้เสมอในเวลาที่เธอนอนหลับ!",
  str_homeland_secret_msg_10403 = "ซานาเอะเป็นคนเร่ร่อนมาจากแดนไกลนะ",
  str_homeland_secret_msg_10404 = "ซานาเอะมักจะพูดคนเดียวเป็นประจำ... หรือว่าเธอนอนละเมอบ่อย?",
  str_homeland_secret_msg_10405 = "รู้สึกว่าห้องแคบมาก ตั้งแต่ที่ซานาเอะกับพี่สาวของเธอเข้ามาพัก...",
  str_homeland_secret_msg_10406 = "ว่ากันว่าคาร์ลีนจะได้เป็นเจ้าเมืองลูโมโพลิส!",
  str_homeland_secret_msg_10407 = "ไม่กี่คืนที่ผ่านมา ดวงตาของคาร์ลีนเปล่งแสงเป็นประกาย!",
  str_homeland_secret_msg_10408 = "รู้อะไรเกี่ยวกับอาวุธของคาร์ลีนมั้ย? มันก่อตัวขึ้นจากลูมินา และไม่มีรูปร่างทางกายภาพ",
  str_homeland_secret_msg_10409 = "ดูเหมือนคาร์ลีนจะได้รับทักษะใหม่ ฉันได้ยินมาว่าเธอสามารถควบคุมลูโมโพลิสให้ลอยไปได้ทุกที่",
  str_homeland_secret_msg_10410 = "เมื่อไม่กี่วันก่อน ดูเหมือนว่าเซียลจะสร้างหุ่นยนต์ตอนนอนหลับนะ",
  str_homeland_secret_msg_10411 = "เกราะขาของเซียลเหมือนจะเป็นส่วนหนึ่งของร่างกายเธอเลย ไม่มีใครเคยเห็นเธอถอดมันออก",
  str_homeland_secret_msg_10412 = "ดูเหมือนว่าเซียลจะวาดรูปเก่งนะ!",
  str_homeland_secret_msg_10413 = "ฟีญ่าสื่อสารกับสัตว์ต่าง ๆ ได้!",
  str_homeland_secret_msg_10414 = "เจ้าไคโลนั่น เขาว่าเป็นญาติกับฟีญ่านะ!",
  str_homeland_secret_msg_10415 = "ดูเหมือนฟีญ่าจะสื่อสารได้กับทุกอย่าง แม้แต่บ้านหลังนี้!",
  str_homeland_secret_msg_10416 = "ตั้งแต่ฟีญ่าเข้ามาอยู่ ก็มีของแวววาวเพิ่มขึ้นมากเลย หรือว่าเธอเป็นดีลเลอร์ค้าอัญมณี?",
  str_homeland_secret_msg_10417 = "เจโน่ทำนายแม่นยังกับตาเห็น ไม่เชื่อก็ลองดูสิ!",
  str_homeland_secret_msg_10418 = "มือของเจโน่เป็นโพรงว่างเปล่า ซ่อนของไว้ในนั้นได้ด้วย!",
  str_homeland_secret_msg_10419 = "ว่ากันว่าเจโน่มีไพ่ลวดลายต่าง ๆ มากมาย แต่ละใบบ่งบอกเหตุการณ์สำคัญในอนาคต!",
  str_homeland_secret_msg_10420 = "ที่จริงเจโน่ไม่มีมายากลอะไรหรอก ที่เขาทำทั้งหมดนั้นเป็นความจริง",
  str_homeland_secret_msg_10421 = "เรนโบว์บอกฉันว่าเรือก็มีวิญญาณ!",
  str_homeland_secret_msg_10422 = "ได้ยินคนพูดว่าเรนโบว์เป็นทายาทของทหารเรือที่หนีจากอิลลูมินา!",
  str_homeland_secret_msg_10423 = "เรนโบว์มีเพื่อนเยอะมาก! แต่พวกเขามีชื่อประหลาด ทั้งเบ็ดตกปลา กระดานไม้ อะไรพวกนี้...",
  str_homeland_secret_msg_10424 = "พอลลักซ์เป็นนางฟ้า! มีคนเคยเห็นรัศมีเหนือศีรษะของเธอ",
  str_homeland_secret_msg_10425 = "เห็นได้ชัดว่า... น้ำตาของพอลลักซ์สามารถเปลี่ยนเป็นอัญมณีได้!",
  str_homeland_secret_msg_10426 = "ดูเหมือนว่า Pollux จะผูกขาดธุรกิจใต้ดินมากมายใน Umbraton และไม่ได้เอาจริงเอาจังกับ Shadowlord ด้วยซ้ำ",
  str_homeland_secret_msg_10427 = "Pollux ค่อนข้างดีกับเด็ก",
  str_homeland_secret_msg_10428 = "ฉันได้ยินมาว่า Casta นอนกับปืนไรเฟิลของเธอในตอนกลางคืน",
  str_homeland_secret_msg_10429 = "บางครั้ง Casta ก็นอนอยู่ใต้เตียงของเธอ",
  str_homeland_secret_msg_10430 = "Casta ดูเหมือนจะโชคดีมากเมื่อเร็ว ๆ นี้ เธอชนะเกมทายนิ้วเกือบทุกครั้ง",
  str_homeland_secret_msg_10431 = "ผู้พิพากษาจูเนียร์เป็นคนธรรมดาจริงๆ นั่นเป็นเหตุผลที่เขาไม่ได้รับการเลื่อนตำแหน่งมาหลายปีแล้ว",
  str_homeland_secret_msg_10432 = "ผู้พิพากษาจูเนียร์เป็นคนที่เล่นโดยหลายคนที่ผลัดกันสวมหน้ากากที่แกล้งทำเป็นเขา",
  str_homeland_secret_msg_10433 = "ผู้พิพากษาจูเนียร์ไม่รู้วิธีทดลองคดีจริงๆ เขาแค่ยุ่ง",
  str_homeland_secret_msg_10434 = "เขาว่ากันว่าลิลิก้ามีชื่อเสียงในอัมบราตัน! เธอมาที่นี่เพื่อหนีจากแฟนๆ ที่รักของเธอ!",
  str_homeland_secret_msg_10435 = "ดูเหมือนว่าลิลิกาจะซื้อหอพักนี้ อย่าลืมจ่ายค่าเช่าของเธอ!",
  str_homeland_secret_msg_10436 = "ลิลิกามาที่นี่โดยตั้งใจจะถ่ายทำสารคดีเกี่ยวกับความรักและความเกลียดชังที่ก่อตัวขึ้นในที่แห่งนี้...",
  str_homeland_secret_msg_10437 = "ลิลิกาเกลียดการแสดงจริงๆ เธอทำเพื่อแฟนๆ เท่านั้น",
  str_homeland_secret_msg_10438 = "พวกเขาบอกว่า Minos อยู่ในแก๊งค์ระหว่างที่เขาอยู่ที่ Umbraton อยู่เคียงข้างเขาดีกว่า...",
  str_homeland_secret_msg_10439 = "ไมนอสแอบเลี้ยงวัวที่ไหนสักแห่งในหอพัก ที่จะอธิบายความมึนเมาเป็นครั้งคราวในตอนกลางคืน...",
  str_homeland_secret_msg_10440 = "Minos ดูเหมือนจะชอบเรื่องผีมาก",
  str_homeland_secret_msg_10441 = "แม้ว่า Minos จะแข็งแกร่งมาก แต่จริงๆ แล้วเขาก็กลัวแมลง! นั่นเป็นเหตุผลว่าทำไมเขาจึงทำความสะอาดทุกอย่างอย่างพิถีพิถัน",
  str_homeland_secret_msg_10442 = "ซาดีอาจจะตัวเล็ก แต่จริงๆ แล้วเธอมีพลังมหาศาล! เธอสามารถรับทั้งบ้าน!",
  str_homeland_secret_msg_10443 = "Sadie บอกว่าเธอใฝ่ฝันที่จะเป็นนักเบสบอลดาราและมาที่ Cloud Gardens เพื่อค้นหาสถานที่สำหรับสร้างสนามเบสบอล!",
  str_homeland_secret_msg_10444 = "ซาดีมีความอยากอาหารบ้า! เธอสามารถกินสเต็กได้หลายร้อยชิ้นโดยไม่ต้องเหนื่อย ไม่ต้องใช้ผัก!",
  str_homeland_secret_msg_10445 = "จริงๆแล้ว Axelia ไม่สามารถพูดได้ ทั้งหมดนี้เป็นข้อความที่บันทึกไว้ล่วงหน้า",
  str_homeland_secret_msg_10446 = "Axelia ดูเด็ก แต่เธอเป็นเจ้าหน้าที่ระดับสูงใน Illumina Federation",
  str_homeland_secret_msg_10447 = "จริงๆแล้ว Axelia กลัวแมลง",
  str_homeland_secret_msg_10448 = "ฉันสังเกตเห็นว่าเตียงของ Axelia ยุบอยู่ใต้ตัวเธอเมื่อสองสามวันก่อน เธออาจจะหนักจริงๆ?",
  str_homeland_secret_msg_10449 = "ฉันได้ยินมาว่าเบเร็ตต้าค่อนข้างดุร้ายในการต่อสู้!",
  str_homeland_secret_msg_10450 = "เห็นได้ชัดว่าเบเร็ตต้าเป็นอาจารย์ของราฟาเอล!",
  str_homeland_secret_msg_10451 = "หอกสองเล่มของเบเร็ตต้าเคลื่อนที่ได้ด้วยตัวมันเอง ดังนั้นอย่าเข้าใกล้เธอในตอนกลางคืน!",
  str_homeland_secret_msg_10452 = "โกลดี้ดูเหมือนจะเกลียดทุกสิ่งที่ขมขื่น!",
  str_homeland_secret_msg_10453 = "สุนัขของโกลดี้ยังเป็นดาราดังอีกด้วย เคยแสดงในโฆษณามาก่อน!",
  str_homeland_secret_msg_10454 = "ฉันได้ยินโกลดี้กรีดร้องครั้งหนึ่ง! ฉันคิดว่าเธอพยายามทำอะไรรัดกุมเกินไป...",
  str_homeland_secret_msg_10455 = "อย่าเข้าข้างโกลดีในทางไม่ดี... แม้ว่าเธอจะดูเหมือนเทวรูปนางฟ้า แต่เธอก็มีความรุนแรงได้",
  str_homeland_secret_msg_10456 = "วิคอาจจะดูเด็ก แต่จริงๆแล้วเป็นคนแก่...",
  str_homeland_secret_msg_10457 = "ครั้งสุดท้ายที่ฉันเห็นวิคหลับ เขาร้องไห้พร้อมกับสัตว์ขนปุกปุยในอ้อมแขนของเขา และพูดว่า \"ฉันกินไม่ได้อีกแล้ว...\"",
  str_homeland_secret_msg_10458 = "คุณสามารถได้ยินเสียงนกร้องในห้องของ Vic ตลอดทั้งคืน มันคือการได้นอนแถวๆ นี้",
  str_homeland_secret_msg_10459 = "วิคไม่ใช่คนดื่มเหล้าสักหน่อย! สัตว์มหัศจรรย์ของเขามักจะดื่มเหล้าทั้งหมดที่เขาสะสมไว้",
  str_homeland_secret_msg_10460 = "บรั่นดีชนะ Umbraton Arm Wrestling Tournament เพียงครั้งเดียว! เธอแข็งแกร่งมาก!",
  str_homeland_secret_msg_10461 = "แม้แต่ Chubbs ก็เริ่มซุบซิบกันตั้งแต่บรั่นดีมาถึง",
  str_homeland_secret_msg_10462 = "คำซุบซิบที่บรั่นดีพวยพุ่งอยู่เสมออาจเป็นเรื่องจริงทั้งหมด เพราะเธอเป็นผู้หญิงที่ซื่อสัตย์",
  str_homeland_secret_msg_10463 = "ฉันได้ยินมาว่าครอบครัวของ Zhong Xu กลายเป็นแมวกันหมด!",
  str_homeland_secret_msg_10464 = "รถเข็นของ Zhong Xu บินได้!",
  str_homeland_secret_msg_10465 = "Zhong Xu ดูเหมือนจะไม่มีความรู้สึกถึงทิศทาง เขาค้นหา \"เข็มทิศ\" อยู่เสมอ",
  str_homeland_secret_msg_10466 = "จงซูไม่สามารถต่อสู้เพื่อรักษาชีวิตไว้ได้ เขาเคยเป็นข้าราชการ นั่นเป็นเหตุผลว่าทำไมเขาถึงมีสินค้าช่างฝีมือทางวัฒนธรรมเล็กๆ น้อยๆ มากมาย",
  str_homeland_secret_msg_10467 = "Yuebai ถูกกล่าวหาว่าว่ายน้ำไม่เป็น แล้วเธอมาเป็นกัปตันเรือได้อย่างไร?",
  str_homeland_secret_msg_10468 = "ฉันรู้สึกว่าเมื่อใดก็ตามที่ Yuebai ยิ้ม สิ่งเลวร้ายกำลังจะเกิดขึ้น...",
  str_homeland_secret_msg_10469 = "นามสกุลของ Yuebai เคยเป็น Sen!",
  str_homeland_secret_msg_10470 = "Yuebai สวมชุดเกราะเต็มรูปแบบตลอดเวลา ราวกับว่าเธอคิดว่ามีใครบางคนกำลังพยายามลอบสังหารเธอในคืนนี้!",
  str_homeland_secret_msg_10471 = "ฉันได้ยินมาว่า Liqing สามารถกินอะไรก็ได้! เขาชอบหญ้าทุกชนิดเป็นพิเศษ... ชาติที่แล้วเขาอาจจะเป็นแพะก็ได้!",
  str_homeland_secret_msg_10472 = "จริงๆ แล้ว ยาของ Liqing ปรุงขึ้นตามคำสอนของปรมาจารย์ด้านการแพทย์ของเขา เขาไม่ได้คิดขึ้นมาเอง",
  str_homeland_secret_msg_10473 = "Liqing มีแมวเป็นน้องชาย!",
  str_homeland_secret_msg_10474 = "Nemesis ชนะ Illumina Rap Contest!",
  str_homeland_secret_msg_10475 = "Nemesis เรียนรู้วิธีเทเลพอร์ตจากสมาชิกของ Courier Union!",
  str_homeland_secret_msg_10476 = "ปรากฎว่าเหล้าทั้งหมดที่ Siobhan ดื่มไม่มีแอลกอฮอล์ แต่เธอก็ยังเมาอยู่ดี ฉันจะว่าอย่างไรได้...",
  str_homeland_secret_msg_10477 = "Siobhan มาที่ Cloud Gardens เพื่อขุดค้นรูปปั้นยักษ์ใหญ่ที่คาดว่า Caelestites ฝังไว้",
